import{_ as n,l as r,o as e,c as i,v as t,p as s,x as o,d as p,i as m,S as L}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"提示压缩 LLMLingua","description":"","frontmatter":{"title":"提示压缩 LLMLingua","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/prompt-compression.md","filePath":"llm/prompt-compression.md","lastUpdated":1789023840000}'),d={name:"llm/prompt-compression.md"};function h(c,a,u,E,_,P){const l=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="提示压缩-llmlingua" tabindex="-1">提示压缩 LLMLingua <a class="header-anchor" href="#提示压缩-llmlingua" aria-label="Permalink to &quot;提示压缩 LLMLingua&quot;">​</a></h1><div class="epigraph"><p>系统提示、检索段落、对话历史里，大量 token 对下一句几乎没有信息。先用小模型打掉它们，大模型按预算看见更短的前缀。</p><footer>—— Jiang et al., LLMLingua, EMNLP 2023；长上下文检索见 LongLLMLingua</footer></div><p><a href="/llm/tensor-decomposition">上一课</a> 压的是权重。本课权重冻结：压的是<strong>提示</strong>。缺口是上下文窗口与 prefill FLOPs 随 token 线性（注意力还更差），RAG 与工具轨迹把前缀撑满。LLMLingua 用小 LM 的困惑度做逐 token 预算控制，迭代删掉「可预测因而信息少」的词。后课词表裁剪回到模型文件内部。不重写 <a href="/llm/prompt-cache">Prompt Cache</a> 的前缀缓存。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户真正的问句往往只有几十 token，前面却挂着几千 token 的说明与文档。完整前缀质量最好，贵。截断尾部或头部会误删关键约束。需要按<strong>信息量</strong>分配预算：不可预测、任务相关的 token 留下，套话与重复检索句删掉。小模型的 PPL 是便宜代理；它与大模型的信息量不完全一致，这是误差来源。</p><p>这不是 KV 量化，也不是 Deja Vu 跳通道。输出词表与权重原封不动。压缩器失败的可见症状是丢约束、丢引用、丢格式，而不是 PPL 微涨。</p><p><span class="marginnote">LongLLMLingua 把问题改成：在多文档里先选段再压 token，避免平均地从每篇各删一半。RAG 场景应走这条，而不是对拼接后的超长串做一次全局删词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算控制器：给定目标压缩比，用小模型对提示分段算条件 PPL，迭代去掉当前最可预测的 token，直到长度达标。保留特殊标记、数字、代码标识符的白名单。与大模型的 chat template 对齐，否则压缩器看见的切分与主模型不同，分数无意义——接到 <a href="/llm/pretokenization-regex">预分词正则</a> 的同一快照纪律。</p><p>评测必须用下游：问答准确、引用是否仍在、格式是否可解析。禁止只报「压缩比 × 速度」而不报任务分。与缓存：压缩后的前缀哈希变了，Prompt Cache 命中率下降，是另一笔账。</p>',10)),(e(),s(L,null,{default:o(()=>[m(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%95%BF%E6%8F%90%E7%A4%BA%22%5D%20--%3E%20S%5B%22%E5%B0%8F%E6%A8%A1%E5%9E%8B%E9%80%90%E6%AE%B5%20PPL%22%5D%0A%20%20S%20--%3E%20B%5B%22%E9%A2%84%E7%AE%97%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%9F%AD%E6%8F%90%E7%A4%BA%22%5D%0A%20%20C%20--%3E%20LLM%5B%22%E4%B8%BB%E6%A8%A1%E5%9E%8B%20prefill%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可预测 token 对交叉熵贡献小，删掉后大模型的条件分布往往仍能补全语法。任务关键实体恰好是高 PPL 的那类，所以代理与目标大体同向。失败在：小模型与大模型的分词器或领域不一致，于是「可预测」指错对象；以及对话里的指代，删了先行词后短提示在主模型里无法还原。</p><p>与 RL 推理链：压缩思维链会把自检步骤删成套话，<a href="/llm/grpo">GRPO</a> 训出的长链不要当普通系统提示压。用户可见问句通常不压。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要对已经短的提示再压。不要把压缩器本身做成又一次大模型调用还宣称省钱。法律、代码、JSON schema 应白名单整段保留。下一课词表裁剪：减的是 embedding 行数，提示仍可以很长。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LLMLingua 压输入 token，不改 \\(W\\)；代理是小模型 PPL。</li><li>验收用下游约束是否还在，不用压缩比本身。</li><li>RAG 先选段再压词；分词器必须与主模型一致。</li><li>推理长链与 schema 不要当套话删。</li><li>出处：Jiang et al., EMNLP 2023 LLMLingua；后续 LongLLMLingua。</li></ul>',7))])}const f=n(d,[["render",h]]);export{A as __pageData,f as default};
